#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define NV 50257
#define NC 256
#define ND 768
#define NL 12
#define NH 12
#define HD 64
static float*W;static long N;
void ln(float*o,float*x,float*g,float*b){
 float m=0,v=0;for(int i=0;i<ND;i++)m+=x[i];m/=ND;
 for(int i=0;i<ND;i++){float d=x[i]-m;v+=d*d;}v/=ND;
 float s=1.0f/sqrtf(v+1e-5f);
 for(int i=0;i<ND;i++)o[i]=(x[i]-m)*s*(g[i]+1)+b[i];
}
float ge(float x){return 0.5f*x*(1.0f+erff(x*0.70710678118654752f));}
// correct creation-order offsets within block
long ln1g=0,ln1b=768,catw=1536,catb=1771008,cpjw=1773312,cpjb=2363136,ln2g=2363904,ln2b=2364672,cfcw=2365440,cfcb=4724736,cpcw=4727808,cpcb=7087104;
void fwd(int*T,int Tn,int trans,float*lgs){
 float*wte=W,*wpe=W+38597376;
 long B0=39383808,S=7087872;
 static float x[NC][ND],h[NC][ND],q[NC][ND],k[NC][ND],v[NC][ND],at[NC][ND],qk[2304],h1[3072],tm[ND];
 for(int t=0;t<Tn;t++)for(int i=0;i<ND;i++)x[t][i]=wte[T[t]*ND+i]+wpe[t*ND+i];
 for(int l=0;l<NL;l++){
  long b=B0+l*S;
  for(int t=0;t<Tn;t++)ln(h[t],x[t],W+b+ln1g,W+b+ln1b);
  for(int t=0;t<Tn;t++){
   for(int j=0;j<2304;j++){float s=W[b+catb+j];for(int i=0;i<ND;i++)s+=h[t][i]*W[b+catw+(trans?j*ND+i:i*2304+j)];qk[j]=s;}
   memcpy(q[t],qk,ND*4);memcpy(k[t],qk+ND,ND*4);memcpy(v[t],qk+2*ND,ND*4);
  }
  for(int hi=0;hi<NH;hi++)for(int t=0;t<Tn;t++){
   float sc[NC];
   for(int t2=0;t2<=t;t2++){float s=0;for(int d=0;d<HD;d++)s+=q[t][hi*HD+d]*k[t2][hi*HD+d];sc[t2]=s*0.125f;}
   float mx=sc[0];for(int t2=1;t2<=t;t2++)if(sc[t2]>mx)mx=sc[t2];
   float sm=0;for(int t2=0;t2<=t;t2++){sc[t2]=expf(sc[t2]-mx);sm+=sc[t2];}
   for(int t2=0;t2<=t;t2++)sc[t2]/=sm;
   for(int d=0;d<HD;d++){float s=0;for(int t2=0;t2<=t;t2++)s+=sc[t2]*v[t2][hi*HD+d];at[t][hi*HD+d]=s;}
  }
  for(int t=0;t<Tn;t++){
   for(int j=0;j<ND;j++){float s=W[b+cpjb+j];for(int i=0;i<ND;i++)s+=at[t][i]*W[b+cpjw+(trans?j*ND+i:i*ND+j)];tm[j]=s;}
   for(int i=0;i<ND;i++)x[t][i]+=tm[i];
  }
  for(int t=0;t<Tn;t++){
   ln(h[t],x[t],W+b+ln2g,W+b+ln2b);
   for(int j=0;j<3072;j++){float s=W[b+cfcb+j];for(int i=0;i<ND;i++)s+=h[t][i]*W[b+cfcw+(trans?j*ND+i:i*3072+j)];h1[j]=ge(s);}
   for(int j=0;j<ND;j++){float s=W[b+cpcb+j];for(int i=0;i<3072;i++)s+=h1[i]*W[b+cpcw+(trans?j*3072+i:i*ND+j)];tm[j]=s;}
   for(int i=0;i<ND;i++)x[t][i]+=tm[i];
  }
 }
 float*lg=W+N-1536,*lb=W+N-768;
 ln(tm,x[Tn-1],lg,lb);
 for(int i=0;i<NV;i++){float s=0;for(int j=0;j<ND;j++)s+=tm[j]*wte[i*ND+j];lgs[i]=s;}
}
int main(){
 FILE*f=fopen("gpt2-124M.ckpt","rb");fseek(f,0,SEEK_END);N=ftell(f)/4;fseek(f,0,SEEK_SET);
 W=malloc(N*4);if(fread(W,4,N,f)!=N)return 1;fclose(f);
