   fwd(pp[p],pl[p],trans,lgs);
   printf("%s:",pn[p]);
   for(int r=0;r<5;r++){int b=0;for(int i=1;i<NV;i++)if(lgs[i]>lgs[b])b=i;printf(" %d(%.1f)",b,lgs[b]);lgs[b]=-1e9;}
   printf("\n");
  }
 }
