  for(int i=0;i<20;i++){fwd(toks,T,trans,lgs);int b=0;for(int j=1;j<NV;j++)if(lgs[j]>lgs[b])b=j;printf(" %d",b);toks[T++]=b;}
  printf("\n");
 }
 return 0;
}
